"""
Local testing script for Receipt Verifier container
Run: python test_local.py
"""

import requests
import base64
import json
from pathlib import Path

BASE_URL = "http://localhost:8000"

def print_section(title):
    print(f"\n{'='*60}")
    print(f" {title}")
    print(f"{'='*60}\n")

def test_health():
    """Test health endpoint"""
    print_section("TEST 1: Health Check")
    try:
        response = requests.get(f"{BASE_URL}/health", timeout=5)
        print(f"Status: {response.status_code}")
        print(f"Response: {json.dumps(response.json(), indent=2)}")
        return response.status_code == 200
    except Exception as e:
        print(f"❌ Error: {e}")
        return False

def test_verify_image_base64():
    """Test verification with base64 image"""
    print_section("TEST 2: Verify with Base64 Image")
    
    # Load a real receipt image if you have one
    receipt_path = Path("reference_receipt.jpg")
    if receipt_path.exists():
        with open(receipt_path, "rb") as f:
            image_data = f.read()
            image_base64 = base64.b64encode(image_data).decode("utf-8")
    else:
        print("⚠️  reference_receipt.jpg not found. Using dummy base64.")
        image_base64 = ""
    
    payload = {
        "image_base64": image_base64,
        "account_number": "123456789",
        "amount": 500.00,
        "payment_id": "test-payment-001"
    }
    
    try:
        print(f"Sending request with account: {payload['account_number']}, amount: {payload['amount']}")
        response = requests.post(
            f"{BASE_URL}/verify/image",
            json=payload,
            timeout=30  # Give OCR time to process
        )
        print(f"Status: {response.status_code}")
        result = response.json()
        print(f"Response: {json.dumps(result, indent=2)}")
        return response.status_code == 200
    except Exception as e:
        print(f"❌ Error: {e}")
        return False

def test_verify_storage():
    """Test verification with storage URL"""
    print_section("TEST 3: Verify with Storage URL")
    
    payload = {
        "image_path": "receipts/test-receipt.jpg",
        "account_number": "987654321",
        "amount": 1000.00,
        "payment_id": "test-payment-002"
    }
    
    try:
        print(f"Sending request with image_path: {payload['image_path']}")
        response = requests.post(
            f"{BASE_URL}/verify/storage",
            json=payload,
            timeout=30
        )
        print(f"Status: {response.status_code}")
        result = response.json()
        print(f"Response: {json.dumps(result, indent=2)}")
        return response.status_code in [200, 400]  # 400 if image not found (still valid test)
    except Exception as e:
        print(f"❌ Error: {e}")
        return False

def test_invalid_base64():
    """Test with invalid base64"""
    print_section("TEST 4: Invalid Base64 (Error Handling)")
    
    payload = {
        "image_base64": "not-valid-base64!!!",
        "account_number": "123456789",
        "amount": 500.00
    }
    
    try:
        response = requests.post(
            f"{BASE_URL}/verify/image",
            json=payload,
            timeout=5
        )
        print(f"Status: {response.status_code}")
        result = response.json()
        print(f"Response: {json.dumps(result, indent=2)}")
        return response.status_code == 400  # Should return bad request
    except Exception as e:
        print(f"❌ Error: {e}")
        return False

def test_missing_fields():
    """Test with missing required fields"""
    print_section("TEST 5: Missing Required Fields (Error Handling)")
    
    payload = {
        "image_base64": "iVBORw0KGgoAAAA...",
        # Missing account_number and amount
    }
    
    try:
        response = requests.post(
            f"{BASE_URL}/verify/image",
            json=payload,
            timeout=5
        )
        print(f"Status: {response.status_code}")
        result = response.json()
        print(f"Response: {json.dumps(result, indent=2)}")
        return response.status_code == 422  # Unprocessable entity
    except Exception as e:
        print(f"❌ Error: {e}")
        return False

def main():
    print("\n🚀 Receipt Verifier - Local Container Test Suite")
    print(f"Testing at: {BASE_URL}")
    
    results = {
        "Health Check": test_health(),
        "Verify Base64": test_verify_image_base64(),
        "Verify Storage": test_verify_storage(),
        "Invalid Base64": test_invalid_base64(),
        "Missing Fields": test_missing_fields(),
    }
    
    print_section("TEST RESULTS SUMMARY")
    for test_name, passed in results.items():
        status = "✅ PASSED" if passed else "❌ FAILED"
        print(f"{test_name}: {status}")
    
    total = len(results)
    passed = sum(results.values())
    print(f"\nTotal: {passed}/{total} tests passed")
    
    if passed == total:
        print("\n🎉 All tests passed!")
    else:
        print(f"\n⚠️  {total - passed} test(s) failed. Check the output above.")

if __name__ == "__main__":
    try:
        main()
    except KeyboardInterrupt:
        print("\n\n❌ Tests interrupted by user")
    except Exception as e:
        print(f"\n\n❌ Fatal error: {e}")
